// Raw text keeps the ~1 MB startup shell on V8's JSON.parse fast path; the bundler would otherwise
// emit it as a JavaScript object literal. Direct Bun scripts ignore `?raw` and yield an object.
import rawShellInput from '@/features/modules/catalog.shell.json?raw';
import {
  type ModuleCatalogShell,
  parseTrustedModuleCatalogShell,
} from '@/features/modules/module-catalog-shell-source';

// Generated by `bun run catalog:shell` from catalog.preview.json; `module-catalog-shell.test.ts`
// keeps them equal and `bundled-catalog-parse.test.ts` proves this trusted parse matches the full
// Zod schema parse without blocking cold startup.
const rawShellSource: unknown = rawShellInput;
const shell: ModuleCatalogShell = parseTrustedModuleCatalogShell(
  typeof rawShellSource === 'string' ? JSON.parse(rawShellSource) : rawShellSource,
);

const { coreModule } = shell;
if (!coreModule.sourceSetDigest || coreModule.sizes.installedBytes === null) {
  throw new Error('Bundled core catalog metadata is incomplete.');
}

export const BUNDLED_CORE_MODULE = {
  ...coreModule,
  sourceSetDigest: coreModule.sourceSetDigest,
  sizes: { ...coreModule.sizes, installedBytes: coreModule.sizes.installedBytes },
};

/** What each home section holds per the catalog: stable, whatever packs are installed. */
export const SECTION_DOCUMENT_COUNTS = shell.sectionDocumentCounts;

/** Always shipped with core discovery; these entries do not imply an installed tool payload. */
export const TOOL_CATALOG = shell.tools.map((entry) => entry.tool);

const moduleIdsByTool = new Map(shell.tools.map((entry) => [entry.tool.id, entry.moduleId]));

export function moduleIdForTool(toolId: string): string | undefined {
  return moduleIdsByTool.get(toolId);
}
